#!/usr/bin/env bash\nset -euo pipefail\n\n# Mock curl to capture its arguments without making network calls\nCURL_ARGS=\"\"\nfunction curl() {\n  CURL_ARGS=\"$*\"\n  # Simulate a successful JSON response from the GitHub API\n  echo '{"id":1}'\n}\nexport -f curl\n\n# Set required environment variables for the script\nexport GITHUB_TOKEN=\"testtoken\"\nexport GITHUB_REPOSITORY=\"owner/repo\"\nexport COMMENT_ID=\"12345\"\n# Fix RANDOM to make the selection deterministic (first emoji = rocket)\nexport RANDOM=0\n\n# Execute the script and capture its output\noutput=$(bash ./src/add-reaction.sh)\n\nexpected_emoji=\"rocket\"\n\n# Verify script output\nif [[ \"$output\" != \"Added reaction :${expected_emoji}: to comment ${COMMENT_ID}\" ]]; then\n  echo \"FAIL: Unexpected script output: $output\"\n  exit 1\nfi\n\n# Verify that curl was called with the correct URL\nif [[ \"$CURL_ARGS\" != *\"repos/owner/repo/issues/comments/12345/reactions\"* ]]; then\n  echo \"FAIL: Curl URL is incorrect\"\n  exit 1\nfi\n\n# Verify that the payload contains the expected emoji\nif [[ \"$CURL_ARGS\" != *\"\\\"content\\\":\\\"${expected_emoji}\\\"\"* ]]; then\n  echo \"FAIL: Curl payload does not contain expected emoji\"\n  exit 1\nfi\n\necho \"PASS\"\n
